={{ JSON.stringify({ from: $json.confirmationFromEmail, to: [$json.businessNotificationEmail], subject: `New booking: ${$('Extract Call Summary').item.json.customerName} - ${$('Extract Call Summary').item.json.bookingDate}`, text: `New booking taken by the AI phone assistant:

Customer: ${$('Extract Call Summary').item.json.customerName}
Phone: ${$('Extract Call Summary').item.json.customerPhone}
Email: ${$('Extract Call Summary').item.json.customerEmail}
Service: ${$('Extract Call Summary').item.json.service}
Date: ${$('Extract Call Summary').item.json.bookingDate}
Time: ${$('Extract Call Summary').item.json.bookingTime}` }) }}

={{ JSON.stringify({ from: $json.confirmationFromEmail, to: [$json.businessNotificationEmail], subject: `Call transferred to manager - ${$('Extract Call Summary').item.json.transferReason || 'uncertain request'}`, text: `The AI phone assistant transferred a live call to the manager because it couldn't confidently handle the caller's request.

Reason: ${$('Extract Call Summary').item.json.transferReason || '(not captured)'}
Caller number: ${$('Extract Call Summary').item.json.customerPhone || 'unknown'}

This is an FYI only - the call was already transferred live to ${$json.managerPhoneNumber || $json.receptionForwardNumber}, no action needed unless you want to follow up.` }) }}
